import 'package:rsa_encrypt/rsa_encrypt.dart';
import 'package:pointycastle/api.dart' as crypto;

Future<crypto.AsymmetricKeyPair> getKeyPair() async {
  var helper = RsaKeyHelper();
  return helper.computeRSAKeyPair(helper.getSecureRandom());
}

String encrypt(String plain, crypto.PublicKey pub) => RsaEncrypt.encrypt(plain, pub);

String decrypt(String cipher, crypto.PrivateKey priv) => RsaEncrypt.decrypt(cipher, priv);
